#app .cal { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 8px; padding: 8px 10px 10px; box-sizing: border-box; position: relative; }
#app .cal * { box-sizing: border-box; }
#app .hidden { display: none !important; }

/* Top bar */
#app .cal-top { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }
#app .cal-title { flex: 1; min-width: 0; font-weight: 600; font-size: 14.5px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-left: 2px; }
#app .btn.sm { height: 28px; padding: 0 10px; font-size: 12.5px; display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }
#app .btn.sm svg { flex: 0 0 auto; }
#app #filterBtn.active { color: var(--text); background: rgba(var(--accent-rgb), .18); }
#app .badge { font-size: 10.5px; line-height: 16px; padding: 0 5px; border-radius: 999px; background: rgba(var(--accent-rgb), .35); color: var(--text); }
#app .cal.tight .lbl { display: none; }
#app .cal.tight #addBtn, #app .cal.tight #filterBtn { padding: 0 8px; }

/* Filter panel */
#app .filter-panel { flex: 0 0 auto; display: grid; grid-template-columns: repeat(auto-fill, minmax(165px, 1fr)); gap: 2px 6px; padding: 6px; background: var(--panel); border: 1px solid var(--border); border-radius: 10px; }
#app .fp-row { display: flex; align-items: center; gap: 2px; border-radius: 7px; }
#app .fp-row:hover { background: var(--panel-hi); }
#app .fp-toggle { flex: 1; min-width: 0; display: flex; align-items: center; gap: 8px; background: none; border: 0; color: var(--text); font: inherit; font-size: 12.5px; padding: 5px 6px; cursor: pointer; text-align: left; border-radius: 7px; }
#app .fp-row.off .fp-toggle { color: var(--faint); }
#app .sw { width: 15px; height: 15px; flex: 0 0 auto; border-radius: 4px; border: 1.5px solid var(--c); background: var(--c); color: var(--on-accent); display: grid; place-items: center; }
#app .off .sw { background: transparent; color: transparent; }
#app .fp-only { background: none; border: 0; font: inherit; font-size: 11px; color: var(--muted); padding: 3px 7px; border-radius: 6px; cursor: pointer; }
#app .fp-only:hover { color: var(--text); background: var(--panel); }
#app .fp-foot { grid-column: 1 / -1; display: flex; align-items: center; gap: 6px; border-top: 1px solid var(--border); margin-top: 3px; padding-top: 4px; }
#app .fp-foot .fp-row { flex: 1; }

#app .filter-strip { flex: 0 0 auto; display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--muted); padding: 0 2px; min-width: 0; }
#app .filter-strip .fs-txt { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#app .link { background: none; border: 0; padding: 0; color: var(--accent); cursor: pointer; font: inherit; white-space: nowrap; }
#app .link:hover { text-decoration: underline; }

/* Body layout */
#app .cal-body { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 8px; overflow-y: auto; }
#app .cal.wide .cal-body { flex-direction: row; overflow: hidden; gap: 10px; }
#app .month { flex: 0 0 auto; display: flex; flex-direction: column; min-width: 0; }
#app .cal.wide .month { flex: 1.4 1 0; min-height: 0; }

#app .dow { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); font-size: 11px; color: var(--faint); text-align: center; padding-bottom: 4px; }
#app .grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); grid-template-rows: repeat(6, 36px); gap: 2px; }
#app .cal.wide .grid { flex: 1; min-height: 0; grid-template-rows: repeat(6, minmax(0, 1fr)); }

#app .cell { appearance: none; font: inherit; color: var(--text); background: transparent; border: 1px solid transparent; border-radius: 8px; padding: 3px 2px; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 0; min-height: 0; overflow: hidden; }
#app .cell:hover { background: var(--panel-hi); }
#app .cell.out { color: var(--faint); }
#app .cell.sel { background: rgba(var(--accent-rgb), .13); border-color: rgba(var(--accent-rgb), .6); }
#app .cell .num { font-size: 12px; width: 20px; height: 20px; line-height: 20px; text-align: center; border-radius: 50%; flex: 0 0 auto; }
#app .cell.today .num { background: var(--accent); color: var(--on-accent); font-weight: 600; }
#app .dots { display: flex; gap: 3px; justify-content: center; }
#app .dot { width: 5px; height: 5px; border-radius: 50%; background: var(--c); }
#app .dot.done { opacity: .35; }
#app .cal.roomy .cell { align-items: stretch; padding: 3px; }
#app .cal.roomy .cell .num { align-self: flex-start; }
#app .chip { display: block; font-size: 10.5px; line-height: 14px; padding: 0 4px; border-radius: 4px; border-left: 2px solid var(--c); background: var(--panel); color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: left; }
#app .chip.done { opacity: .5; text-decoration: line-through; }
#app .cell.out .chip { opacity: .6; }
#app .more { font-size: 10px; color: var(--muted); text-align: left; padding-left: 4px; }

/* Agenda */
#app .agenda { flex: 1 1 0; min-height: 150px; display: flex; flex-direction: column; gap: 6px; overflow-y: auto; background: var(--panel); border: 1px solid var(--border); border-radius: 10px; padding: 8px; }
#app .cal.wide .agenda { min-height: 0; min-width: 220px; }
#app .ag-head { display: flex; align-items: center; gap: 6px; }
#app .ag-title { flex: 1; min-width: 0; }
#app .day-title { font-weight: 600; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#app .sub { font-size: 11.5px; color: var(--muted); }

#app .day-list { display: flex; flex-direction: column; gap: 4px; }
#app .item { display: flex; align-items: center; gap: 8px; min-height: 36px; padding: 5px 5px 5px 8px; border-radius: 8px; background: var(--panel); border-left: 3px solid var(--c); }
#app .item:hover { background: var(--panel-hi); }
#app .item .main { flex: 1; min-width: 0; cursor: pointer; }
#app .item.confirm .main { cursor: default; }
#app .ttl { font-size: 13px; line-height: 1.3; color: var(--text); overflow-wrap: anywhere; }
#app .meta { font-size: 11.5px; color: var(--muted); margin-top: 1px; }
#app .item.done .ttl { text-decoration: line-through; color: var(--muted); }
#app .acts { display: flex; align-items: center; gap: 4px; opacity: 0; transition: opacity .12s; }
#app .item:hover .acts, #app .item:focus-within .acts, #app .acts.show { opacity: 1; }
#app .item .icon-btn { width: 24px; height: 24px; }
#app .chk { width: 18px; height: 18px; flex: 0 0 auto; border-radius: 50%; border: 1.5px solid var(--c); background: transparent; color: transparent; display: grid; place-items: center; padding: 0; cursor: pointer; }
#app .chk:hover { background: var(--panel-hi); color: var(--muted); }
#app .item.done .chk { background: var(--c); color: var(--on-accent); }
#app .mini { font: inherit; font-size: 11.5px; white-space: nowrap; border: 1px solid var(--border); background: transparent; color: var(--muted); border-radius: 6px; padding: 2px 8px; cursor: pointer; }
#app .mini:hover { color: var(--text); background: var(--panel-hi); }
#app .mini.danger { color: var(--warn); border-color: var(--warn); }

#app .sec { font-size: 11px; letter-spacing: .05em; text-transform: uppercase; color: var(--faint); margin: 8px 2px 2px; }
#app .sec.warn { color: var(--warn); }
#app button.sec { display: flex; align-items: center; gap: 4px; background: none; border: 0; padding: 0; font-family: inherit; cursor: pointer; text-align: left; }
#app button.sec:hover { color: var(--muted); }
#app button.sec svg { transition: transform .15s; }
#app button.sec.open svg { transform: rotate(90deg); }
#app .empty { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 18px 8px; text-align: center; color: var(--muted); font-size: 12.5px; }
#app .hidden-note { font-size: 11.5px; color: var(--faint); padding: 2px; }

/* Editor */
#app .editor { display: flex; flex-direction: column; gap: 8px; padding: 10px; border-radius: 10px; border: 1px solid var(--border); background: var(--panel); flex: 0 0 auto; }
#app .seg { display: flex; gap: 2px; padding: 2px; border-radius: 8px; background: var(--panel); border: 1px solid var(--border); }
#app .seg button { flex: 1; font: inherit; font-size: 12.5px; border: 0; background: transparent; color: var(--muted); padding: 4px 6px; border-radius: 6px; cursor: pointer; }
#app .seg button:hover:not(:disabled) { color: var(--text); }
#app .seg button.on { background: rgba(var(--accent-rgb), .22); color: var(--text); }
#app .seg button:disabled { opacity: .35; cursor: default; }
#app .editor input, #app .editor select { width: 100%; min-width: 0; }
#app .editor input[type="date"], #app .editor input[type="time"] { color-scheme: dark; }
#app .row { display: flex; gap: 6px; flex-wrap: wrap; }
#app .row > label { flex: 1 1 100px; min-width: 0; display: flex; flex-direction: column; gap: 3px; font-size: 11px; color: var(--muted); }
#app .row.end { justify-content: flex-end; }
#app .editor.is-task .ev-only { display: none; }
#app .editor:not(.is-task) .task-only { display: none; }
#app .hint { font-size: 11.5px; color: var(--muted); }
#app .err { font-size: 12px; color: var(--warn); }
#app .hint:empty, #app .err:empty { display: none; }

