const root = document.querySelector('#app .cal');
const q = (s) => root.querySelector(s);
const el = {
  title: q('#monthTitle'), prev: q('#prevBtn'), next: q('#nextBtn'), todayBtn: q('#todayBtn'),
  filterBtn: q('#filterBtn'), filterBadge: q('#filterBadge'), filterPanel: q('#filterPanel'), strip: q('#filterStrip'),
  addBtn: q('#addBtn'), dow: q('#dow'), grid: q('#grid'), agenda: q('#agenda'),
  dayTitle: q('#dayTitle'), daySub: q('#daySub'), planBtn: q('#planBtn'), list: q('#dayList'),
  form: q('#editor'), seg: q('#typeSeg'), fTitle: q('#fTitle'), fDate: q('#fDate'), fDateLabel: q('#fDateLabel'),
  fTime: q('#fTime'), fEnd: q('#fEnd'), fCat: q('#fCat'), fRepeat: q('#fRepeat'), fHint: q('#fHint'),
  fErr: q('#fErr'), fCancel: q('#fCancel'), fSave: q('#fSave'),
};

const CATS = [
  { key: 'event', label: 'Events', one: 'Event', color: 'var(--accent)' },
  { key: 'activity', label: 'Activities', one: 'Activity', color: 'var(--ok)' },
  { key: 'homework', label: 'Homework', one: 'Homework', color: 'var(--warn)' },
  { key: 'email', label: 'Email', one: 'Email', color: '#5aa9e6' },
  { key: 'unfinished', label: 'Unfinished', one: 'Unfinished', color: '#b48cf0' },
  { key: 'other', label: 'Other tasks', one: 'Task', color: 'var(--muted)' },
];
const CAT = Object.fromEntries(CATS.map((c) => [c.key, c]));
const TASK_CATS = ['homework', 'email', 'unfinished', 'other'];
const REPEAT_LABEL = { daily: 'Daily', weekdays: 'Weekdays', weekly: 'Weekly', monthly: 'Monthly', yearly: 'Yearly' };

const ICON = {
  check: '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>',
  trash: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/></svg>',
  chev: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg>',
};

// ---------- helpers ----------
const pad = (n) => String(n).padStart(2, '0');
const toDS = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const isDS = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
const isTime = (s) => typeof s === 'string' && /^\d{2}:\d{2}$/.test(s);
const parseDS = (s) => { const [y, m, d] = String(s).split('-').map(Number); return new Date(y, (m || 1) - 1, d || 1); };
const fmtTime = (t) => {
  if (!isTime(t)) return '';
  const [h, m] = t.split(':').map(Number);
  return new Date(2000, 0, 1, h, m).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
};
const shortDate = (ds) => parseDS(ds).toLocaleDateString([], { month: 'short', day: 'numeric' });
const nowHM = () => { const d = new Date(); return pad(d.getHours()) + ':' + pad(d.getMinutes()); };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = () => 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
const getToday = () => { try { const t = overlay.today(); return isDS(t) ? t : toDS(new Date()); } catch { return toDS(new Date()); } };
const safe = (p) => Promise.resolve(p).catch(() => null);

function relDay(ds) {
  const diff = Math.round((parseDS(ds) - parseDS(today)) / 86400000);
  if (diff === 0) return 'Today';
  if (diff === 1) return 'Tomorrow';
  if (diff === -1) return 'Yesterday';
  return diff > 1 ? `In ${diff} days` : `${-diff} days ago`;
}

// ---------- state ----------
let today = getToday();
const t0 = parseDS(today);
const state = {
  events: [],
  tasks: [],
  filter: { hidden: [], showDone: true },
  view: { y: t0.getFullYear(), m: t0.getMonth() },
  selected: today,
  editing: null,   // { mode: 'new'|'edit', type: 'event'|'activity'|'task', id? }
  confirm: null,   // key of the item awaiting delete confirmation
  filterOpen: false,
  showUndated: false,
};
let notified = {};
let lastType = 'event';
let saving = false;

const [storedEvents, storedFilter, storedNotified, storedType, taskList] = await Promise.all([
  safe(overlay.storage.get('events')),
  safe(overlay.storage.get('filter')),
  safe(overlay.storage.get('notified')),
  safe(overlay.storage.get('lastType')),
  safe(overlay.tasks.list()),
]);
state.events = Array.isArray(storedEvents)
  ? storedEvents.filter((e) => e && e.id && isDS(e.date) && typeof e.title === 'string')
  : [];
if (storedFilter && typeof storedFilter === 'object') {
  state.filter.hidden = Array.isArray(storedFilter.hidden) ? storedFilter.hidden.filter((k) => CAT[k]) : [];
  state.filter.showDone = storedFilter.showDone !== false;
}
if (storedNotified && typeof storedNotified === 'object') notified = storedNotified;
if (['event', 'activity', 'task'].includes(storedType)) lastType = storedType;
state.tasks = Array.isArray(taskList) ? taskList : [];

const saveEvents = () => safe(overlay.storage.set('events', state.events));
const saveFilter = () => safe(overlay.storage.set('filter', state.filter));

// ---------- data ----------
const taskCat = (t) => (TASK_CATS.includes(t && t.category) ? t.category : 'other');
const visible = (cat) => !state.filter.hidden.includes(cat);

function occursOn(e, ds) {
  if (!isDS(e.date)) return false;
  if (Array.isArray(e.skip) && e.skip.includes(ds)) return false;
  if (ds === e.date) return true;
  if (!e.repeat || e.repeat === 'none' || ds < e.date) return false;
  const a = parseDS(e.date), b = parseDS(ds);
  switch (e.repeat) {
    case 'daily': return true;
    case 'weekdays': return b.getDay() >= 1 && b.getDay() <= 5;
    case 'weekly': return a.getDay() === b.getDay();
    case 'monthly': return a.getDate() === b.getDate();
    case 'yearly': return a.getDate() === b.getDate() && a.getMonth() === b.getMonth();
    default: return false;
  }
}

function taskItem(t) {
  return {
    type: 'task', cat: taskCat(t), id: t.id, key: 't:' + t.id,
    title: String(t.title || '').trim() || '(untitled)',
    time: isDS(t.due) && isTime(t.time) ? t.time : '',
    end: '', done: !!t.done, src: t,
  };
}
function eventItem(e) {
  const time = isTime(e.time) ? e.time : '';
  return {
    type: 'event', cat: e.kind === 'activity' ? 'activity' : 'event', id: e.id, key: 'e:' + e.id,
    title: e.title || '(untitled)', time, end: time && isTime(e.end) ? e.end : '',
    repeat: e.repeat, done: false, src: e,
  };
}
function cmpItems(a, b) {
  if (a.done !== b.done) return a.done ? 1 : -1;
  if (a.time !== b.time) {
    if (!a.time) return -1;
    if (!b.time) return 1;
    return a.time < b.time ? -1 : 1;
  }
  if (a.type !== b.type) return a.type === 'event' ? -1 : 1;
  return a.title.localeCompare(b.title);
}
function itemsOn(ds, all = false) {
  const out = [];
  for (const e of state.events) {
    if (!occursOn(e, ds)) continue;
    const it = eventItem(e);
    if (all || visible(it.cat)) out.push(it);
  }
  for (const t of state.tasks) {
    if (!t || t.due !== ds) continue;
    const it = taskItem(t);
    if (all || (visible(it.cat) && (state.filter.showDone || !it.done))) out.push(it);
  }
  return out.sort(cmpItems);
}
function findByKey(key) {
  const i = key.indexOf(':');
  const kind = key.slice(0, i), id = key.slice(i + 1);
  if (kind === 't') { const t = state.tasks.find((x) => x && String(x.id) === id); return t ? taskItem(t) : null; }
  const e = state.events.find((x) => String(x.id) === id);
  return e ? eventItem(e) : null;
}
async function refreshTasks() {
  const list = await safe(overlay.tasks.list());
  if (Array.isArray(list)) state.tasks = list;
}
async function taskUpdate(id, patch) {
  try { await overlay.tasks.update(id, patch); } catch {}
  await refreshTasks();
  render();
}

// ---------- rendering ----------
let wide = false, roomy = false, lastGridH = 0;

function renderDow() {
  el.dow.innerHTML = Array.from({ length: 7 }, (_, i) =>
    `<span>${esc(new Date(2026, 0, 4 + i).toLocaleDateString([], { weekday: 'short' }))}</span>`).join('');
}

function renderGrid() {
  const { y, m } = state.view;
  el.title.textContent = new Date(y, m, 1).toLocaleDateString([], { month: 'long', year: 'numeric' });
  const offset = new Date(y, m, 1).getDay();
  const maxChips = roomy ? Math.max(1, Math.floor((el.grid.clientHeight / 6 - 26) / 16)) : 0;
  let html = '';
  for (let i = 0; i < 42; i++) {
    const d = new Date(y, m, 1 - offset + i);
    const ds = toDS(d);
    const items = itemsOn(ds);
    const cls = ['cell'];
    if (d.getMonth() !== m) cls.push('out');
    if (ds === today) cls.push('today');
    if (ds === state.selected) cls.push('sel');
    let marks = '';
    if (items.length) {
      if (roomy) {
        const shown = items.length > maxChips ? items.slice(0, Math.max(0, maxChips - 1)) : items;
        marks = shown.map((it) => `<span class="chip${it.done ? ' done' : ''}" style="--c:${CAT[it.cat].color}">${esc(it.title)}</span>`).join('');
        if (shown.length < items.length) marks += `<span class="more">+${items.length - shown.length} more</span>`;
      } else {
        marks = `<span class="dots">${items.slice(0, 4).map((it) => `<i class="dot${it.done ? ' done' : ''}" style="--c:${CAT[it.cat].color}"></i>`).join('')}</span>`;
      }
    }
    const tip = items.map((it) => (it.time ? fmtTime(it.time) + '  ' : '') + it.title).join('\n');
    html += `<button type="button" class="${cls.join(' ')}" data-date="${ds}"${tip ? ` title="${esc(tip)}"` : ''}><span class="num">${d.getDate()}</span>${marks}</button>`;
  }
  el.grid.innerHTML = html;
}

function itemHTML(it, opt = {}) {
  const c = CAT[it.cat];
  const style = `--c:${c.color}`;
  const key = esc(it.key);
  if (state.confirm === it.key) {
    const rep = it.type === 'event' && REPEAT_LABEL[it.repeat];
    return `<div class="item confirm" style="${style}" data-key="${key}">
      <div class="main"><div class="ttl">Delete “${esc(it.title)}”?</div>${rep ? '<div class="meta">This repeats. Remove just this day or the whole series.</div>' : ''}</div>
      <div class="acts show">
        ${rep ? '<button type="button" class="mini" data-act="skip">This day</button><button type="button" class="mini danger" data-act="delall">All</button>'
              : '<button type="button" class="mini danger" data-act="delall">Delete</button>'}
        <button type="button" class="mini" data-act="nodel">Cancel</button>
      </div></div>`;
  }
  const meta = [];
  if (opt.extra) meta.push(opt.extra);
  if (it.type === 'task') { if (it.time) meta.push('Due ' + fmtTime(it.time)); }
  else meta.push(it.time ? fmtTime(it.time) + (it.end ? ' – ' + fmtTime(it.end) : '') : 'All day');
  meta.push(c.one);
  if (it.type === 'event' && REPEAT_LABEL[it.repeat]) meta.push(REPEAT_LABEL[it.repeat]);
  return `<div class="item${it.done ? ' done' : ''}" style="${style}" data-key="${key}">
    ${it.type === 'task' ? `<button type="button" class="chk" data-act="toggle" title="${it.done ? 'Mark as not done' : 'Mark as done'}">${ICON.check}</button>` : ''}
    <div class="main" data-act="edit" title="Click to edit"><div class="ttl">${esc(it.title)}</div><div class="meta">${esc(meta.join(' · '))}</div></div>
    ${opt.move ? '<button type="button" class="mini" data-act="movetoday">Move to today</button>' : ''}
    <div class="acts"><button type="button" class="icon-btn" data-act="del" title="Delete">${ICON.trash}</button></div>
  </div>`;
}

function renderAgenda() {
  const ds = state.selected;
  const d = parseDS(ds);
  const sameYear = d.getFullYear() === parseDS(today).getFullYear();
  el.dayTitle.textContent = d.toLocaleDateString([], { weekday: 'long', month: 'short', day: 'numeric', ...(sameYear ? {} : { year: 'numeric' }) });

  const items = itemsOn(ds);
  const hiddenCount = itemsOn(ds, true).length - items.length;
  el.daySub.textContent = relDay(ds) + ' · ' + (items.length ? `${items.length} item${items.length === 1 ? '' : 's'}` : 'nothing planned');

  let html = '';
  if (ds === today) {
    const overdue = state.tasks
      .filter((t) => t && !t.done && isDS(t.due) && t.due < today && visible(taskCat(t)))
      .sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0));
    if (overdue.length) {
      html += '<div class="sec warn">Overdue</div>';
      html += overdue.map((t) => itemHTML(taskItem(t), { extra: 'Was due ' + shortDate(t.due), move: true })).join('');
      html += '<div class="sec">Today</div>';
    }
  }

  if (items.length) {
    html += items.map((it) => itemHTML(it)).join('');
    if (hiddenCount) html += `<div class="hidden-note">${hiddenCount} more hidden by filters · <button type="button" class="link" data-act="clearfilter">Show all</button></div>`;
  } else {
    html += `<div class="empty">
      <div>${hiddenCount ? `Nothing here matches your filters (${hiddenCount} hidden).` : 'Nothing planned for this day.'}</div>
      ${hiddenCount ? '<button type="button" class="btn ghost sm" data-act="clearfilter">Show all</button>' : '<button type="button" class="btn ghost sm" data-act="addhere">Add something</button>'}
    </div>`;
  }

  const undated = state.tasks.filter((t) => t && !t.done && !isDS(t.due) && visible(taskCat(t)));
  if (undated.length) {
    html += `<button type="button" class="sec${state.showUndated ? ' open' : ''}" data-act="undated">${ICON.chev}Tasks with no due date · ${undated.length}</button>`;
    if (state.showUndated) {
      html += undated.map((t) => {
        const it = taskItem(t);
        return `<div class="item" style="--c:${CAT[it.cat].color}" data-key="${esc(it.key)}">
          <div class="main" data-act="edit" title="Click to edit"><div class="ttl">${esc(it.title)}</div><div class="meta">${esc(CAT[it.cat].one)}</div></div>
          <button type="button" class="mini" data-act="setdue" title="Set the due date to the selected day">Due ${esc(shortDate(ds))}</button>
        </div>`;
      }).join('');
    }
  }
  el.list.innerHTML = html;
}

function renderFilter() {
  const f = state.filter;
  const vis = CATS.filter((c) => !f.hidden.includes(c.key));
  el.filterPanel.classList.toggle('hidden', !state.filterOpen);
  if (state.filterOpen) {
    el.filterPanel.innerHTML = CATS.map((c) => {
      const off = f.hidden.includes(c.key);
      const isOnly = vis.length === 1 && vis[0].key === c.key;
      return `<div class="fp-row${off ? ' off' : ''}" style="--c:${c.color}">
        <button type="button" class="fp-toggle" data-fact="toggle" data-cat="${c.key}" title="${off ? 'Show' : 'Hide'} ${esc(c.label)}"><span class="sw">${ICON.check}</span>${esc(c.label)}</button>
        <button type="button" class="fp-only" data-fact="only" data-cat="${c.key}" title="${isOnly ? 'Show everything again' : 'Show only ' + esc(c.label)}">${isOnly ? 'All' : 'Only'}</button>
      </div>`;
    }).join('') + `<div class="fp-foot">
        <div class="fp-row${f.showDone ? '' : ' off'}" style="--c:var(--muted)">
          <button type="button" class="fp-toggle" data-fact="done"><span class="sw">${ICON.check}</span>Completed tasks</button>
        </div>
        <button type="button" class="btn ghost sm" data-fact="all">Show all</button>
      </div>`;
  }

  let txt = '';
  if (f.hidden.length) {
    txt = vis.length === 0 ? 'Everything is hidden'
      : vis.length <= 2 ? 'Only ' + vis.map((c) => c.label).join(' & ')
      : 'Hiding ' + CATS.filter((c) => f.hidden.includes(c.key)).map((c) => c.label).join(', ');
  }
  if (!f.showDone) txt += txt ? ' · completed hidden' : 'Completed tasks hidden';
  el.strip.classList.toggle('hidden', !txt || state.filterOpen);
  el.strip.innerHTML = txt ? `<span class="fs-txt">${esc(txt)}</span><button type="button" class="link" data-fact="all">Show all</button>` : '';

  const active = f.hidden.length > 0 || !f.showDone;
  el.filterBtn.classList.toggle('active', active || state.filterOpen);
  el.filterBadge.classList.toggle('hidden', !f.hidden.length);
  el.filterBadge.textContent = `${vis.length}/${CATS.length}`;
}

function render() {
  renderGrid();
  renderAgenda();
  renderFilter();
  updatePill();
}

// ---------- pill ----------
let lastPill = null;
function fitPill(title, suffix) {
  const room = 40 - (suffix ? suffix.length + 1 : 0);
  const t = title.length > room ? title.slice(0, Math.max(1, room - 1)) + '…' : title;
  return suffix ? t + ' ' + suffix : t;
}
function updatePill() {
  const items = itemsOn(today, true).filter((i) => !i.done);
  const now = nowHM();
  let text = '';
  const current = items.find((i) => i.type === 'event' && i.time && i.end && i.time <= now && i.end > now);
  const next = items.find((i) => i.time && i.time >= now);
  const dueToday = items.filter((i) => i.type === 'task').length;
  if (current) text = fitPill('Now: ' + current.title, '');
  else if (next) text = fitPill(next.title, fmtTime(next.time));
  else if (dueToday) text = `${dueToday} task${dueToday === 1 ? '' : 's'} due today`;
  if (text !== lastPill) {
    lastPill = text;
    try { overlay.pill?.setStatus?.(text); } catch {}
  }
}
function checkNotify() {
  const d = new Date();
  const nowMin = d.getHours() * 60 + d.getMinutes();
  let changed = false;
  for (const k of Object.keys(notified)) if (notified[k] !== today) { delete notified[k]; changed = true; }
  for (const it of itemsOn(today, true)) {
    if (it.done || !it.time) continue;
    const [h, m] = it.time.split(':').map(Number);
    const start = h * 60 + m;
    if (nowMin < start || nowMin >= start + 5) continue;
    const k = it.key + '|' + today;
    if (notified[k]) continue;
    notified[k] = today;
    changed = true;
    try { overlay.pill?.notify?.(fitPill((it.type === 'task' ? 'Due: ' : 'Now: ') + it.title, ''), 10); } catch {}
  }
  if (changed) safe(overlay.storage.set('notified', notified));
}

// ---------- editor ----------
function openEditor(mode, item) {
  state.confirm = null;
  el.fErr.textContent = '';
  if (mode === 'new') {
    state.editing = { mode: 'new', type: lastType };
    el.fTitle.value = '';
    el.fDate.value = state.selected;
    el.fTime.value = '';
    el.fEnd.value = '';
    el.fCat.value = 'homework';
    el.fRepeat.value = 'none';
  } else if (item.type === 'task') {
    const t = item.src;
    state.editing = { mode: 'edit', type: 'task', id: t.id };
    el.fTitle.value = t.title || '';
    el.fDate.value = isDS(t.due) ? t.due : '';
    el.fTime.value = isTime(t.time) ? t.time : '';
    el.fEnd.value = '';
    el.fCat.value = taskCat(t);
    el.fRepeat.value = 'none';
  } else {
    const e = item.src;
    state.editing = { mode: 'edit', type: e.kind === 'activity' ? 'activity' : 'event', id: e.id };
    el.fTitle.value = e.title || '';
    el.fDate.value = e.date;
    el.fTime.value = isTime(e.time) ? e.time : '';
    el.fEnd.value = isTime(e.end) ? e.end : '';
    el.fCat.value = 'homework';
    el.fRepeat.value = REPEAT_LABEL[e.repeat] ? e.repeat : 'none';
  }
  syncEditor();
  el.form.classList.remove('hidden');
  el.agenda.scrollTop = 0;
  renderAgenda();
  setTimeout(() => el.fTitle.focus(), 0);
}
function syncEditor() {
  const ed = state.editing;
  if (!ed) return;
  const isTask = ed.type === 'task';
  el.form.classList.toggle('is-task', isTask);
  el.seg.querySelectorAll('button').forEach((b) => {
    b.classList.toggle('on', b.dataset.type === ed.type);
    b.disabled = ed.mode === 'edit' && (ed.type === 'task') !== (b.dataset.type === 'task');
  });
  el.fDateLabel.textContent = isTask ? 'Due date (optional)' : 'Date';
  el.fSave.textContent = ed.mode === 'edit' ? 'Save' : 'Add';
  el.fTitle.placeholder = isTask ? 'What needs doing?' : ed.type === 'activity' ? 'What are you doing?' : 'Event name';
  el.fHint.textContent = !isTask && ed.mode === 'edit' && el.fRepeat.value !== 'none' ? 'Changes apply to every repeat.' : '';
}
function closeEditor() {
  state.editing = null;
  el.form.classList.add('hidden');
  el.fErr.textContent = '';
}

el.seg.addEventListener('click', (e) => {
  const b = e.target.closest('button[data-type]');
  if (!b || b.disabled || !state.editing) return;
  state.editing.type = b.dataset.type;
  if (b.dataset.type !== 'task' && !el.fDate.value) el.fDate.value = state.selected;
  el.fErr.textContent = '';
  syncEditor();
  el.fTitle.focus();
});
el.fRepeat.addEventListener('change', syncEditor);
el.fCancel.addEventListener('click', closeEditor);

el.form.addEventListener('submit', async (e) => {
  e.preventDefault();
  const ed = state.editing;
  if (!ed || saving) return;
  const err = (m) => { el.fErr.textContent = m; };
  const title = el.fTitle.value.trim();
  const date = el.fDate.value;
  const time = el.fTime.value;
  const end = el.fEnd.value;
  if (!title) { el.fTitle.focus(); return err('Give it a title.'); }

  if (ed.type === 'task') {
    if (time && !date) return err('Pick a due date to set a time.');
    saving = true;
    try {
      if (ed.mode === 'new') {
        const payload = { title, category: el.fCat.value };
        if (date) payload.due = date;
        if (date && time) payload.time = time;
        const added = await overlay.tasks.add(payload);
        if (!Array.isArray(added) || !added.length) return err('A task with that title already exists.');
      } else {
        await overlay.tasks.update(ed.id, { title, category: el.fCat.value, due: date || null, time: date && time ? time : null });
      }
      await refreshTasks();
    } catch {
      return err('Could not save the task. Try again.');
    } finally {
      saving = false;
    }
  } else {
    if (!date) return err('Pick a date.');
    if (time && end && end <= time) return err('End time should be after the start time.');
    const data = {
      title, date, kind: ed.type,
      time: time || undefined,
      end: time && end ? end : undefined,
      repeat: el.fRepeat.value !== 'none' ? el.fRepeat.value : undefined,
    };
    if (ed.mode === 'new') {
      state.events.push({ id: uid(), ...data });
    } else {
      const idx = state.events.findIndex((x) => x.id === ed.id);
      if (idx === -1) return err('This item no longer exists.');
      const prev = state.events[idx];
      state.events[idx] = { ...prev, ...data, skip: data.repeat ? prev.skip : undefined };
    }
    await saveEvents();
  }

  if (ed.mode === 'new') {
    lastType = ed.type;
    safe(overlay.storage.set('lastType', lastType));
  }
  if (date) { state.selected = date; goToMonth(date); }
  closeEditor();
  render();
});

// ---------- navigation ----------
function goToMonth(ds) {
  const d = parseDS(ds);
  state.view = { y: d.getFullYear(), m: d.getMonth() };
}
function selectDate(ds) {
  state.selected = ds;
  state.confirm = null;
  const d = parseDS(ds);
  if (d.getMonth() !== state.view.m || d.getFullYear() !== state.view.y) goToMonth(ds);
  if (state.editing && state.editing.mode === 'new') el.fDate.value = ds;
  render();
}
function shiftMonth(n) {
  const d = new Date(state.view.y, state.view.m + n, 1);
  state.view = { y: d.getFullYear(), m: d.getMonth() };
  const t = parseDS(today);
  state.selected = t.getFullYear() === state.view.y && t.getMonth() === state.view.m ? today : toDS(d);
  state.confirm = null;
  render();
}

el.prev.addEventListener('click', () => shiftMonth(-1));
el.next.addEventListener('click', () => shiftMonth(1));
el.todayBtn.addEventListener('click', () => selectDate(today));
el.addBtn.addEventListener('click', () => openEditor('new'));
el.filterBtn.addEventListener('click', () => { state.filterOpen = !state.filterOpen; renderFilter(); });

el.grid.addEventListener('click', (e) => {
  const c = e.target.closest('.cell');
  if (c) selectDate(c.dataset.date);
});
el.grid.addEventListener('dblclick', (e) => {
  const c = e.target.closest('.cell');
  if (!c) return;
  selectDate(c.dataset.date);
  openEditor('new');
});

function onFilterClick(e) {
  const b = e.target.closest('[data-fact]');
  if (!b) return;
  const f = state.filter;
  const cat = b.dataset.cat;
  switch (b.dataset.fact) {
    case 'toggle':
      f.hidden = f.hidden.includes(cat) ? f.hidden.filter((k) => k !== cat) : [...f.hidden, cat];
      break;
    case 'only': {
      const others = CATS.map((c) => c.key).filter((k) => k !== cat);
      const already = !f.hidden.includes(cat) && others.every((k) => f.hidden.includes(k));
      f.hidden = already ? [] : others;
      break;
    }
    case 'done': f.showDone = !f.showDone; break;
    case 'all': f.hidden = []; f.showDone = true; break;
  }
  saveFilter();
  render();
}
el.filterPanel.addEventListener('click', onFilterClick);
el.strip.addEventListener('click', onFilterClick);

el.planBtn.addEventListener('click', () => {
  const ds = state.selected;
  const label = parseDS(ds).toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric' });
  const items = itemsOn(ds, true);
  const lines = items.map((i) => {
    const when = i.time ? fmtTime(i.time) + (i.end ? '–' + fmtTime(i.end) : '') : (i.type === 'task' ? 'any time' : 'all day');
    return `- ${when}: ${i.title} (${CAT[i.cat].one}${i.done ? ', done' : ''})`;
  });
  const prompt = items.length
    ? `Here's my calendar for ${label}:\n${lines.join('\n')}\n\nHelp me plan this day: suggest an order, when to fit in my tasks, and anything I might be missing.`
    : `I have nothing on my calendar for ${label} yet. Help me plan that day, taking my open tasks into account.`;
  try { overlay.openChat(prompt); } catch {}
});

el.list.addEventListener('click', async (e) => {
  const a = e.target.closest('[data-act]');
  if (!a) return;
  const act = a.dataset.act;
  if (act === 'addhere') return openEditor('new');
  if (act === 'clearfilter') { state.filter.hidden = []; state.filter.showDone = true; saveFilter(); return render(); }
  if (act === 'undated') { state.showUndated = !state.showUndated; return renderAgenda(); }

  const row = a.closest('[data-key]');
  if (!row) return;
  const key = row.dataset.key;
  const it = findByKey(key);
  if (!it) return;
  const editingThis = state.editing && state.editing.mode === 'edit' && String(state.editing.id) === String(it.id);

  switch (act) {
    case 'edit':
      openEditor('edit', it);
      break;
    case 'toggle':
      it.src.done = !it.done; // optimistic
      render();
      await taskUpdate(it.id, { done: !it.done });
      break;
    case 'del':
      state.confirm = key;
      renderAgenda();
      break;
    case 'nodel':
      state.confirm = null;
      renderAgenda();
      break;
    case 'delall':
      state.confirm = null;
      if (editingThis) closeEditor();
      if (it.type === 'task') {
        state.tasks = state.tasks.filter((t) => t !== it.src);
        render();
        try { await overlay.tasks.remove(it.id); } catch {}
        await refreshTasks();
      } else {
        state.events = state.events.filter((x) => x.id !== it.id);
        await saveEvents();
      }
      render();
      break;
    case 'skip': {
      state.confirm = null;
      const ev = state.events.find((x) => x.id === it.id);
      if (ev) {
        ev.skip = Array.from(new Set([...(Array.isArray(ev.skip) ? ev.skip : []), state.selected]));
        await saveEvents();
      }
      render();
      break;
    }
    case 'movetoday':
      await taskUpdate(it.id, { due: today });
      break;
    case 'setdue':
      await taskUpdate(it.id, { due: state.selected });
      break;
  }
});

root.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  if (state.editing) closeEditor();
  else if (state.confirm) { state.confirm = null; renderAgenda(); }
  else if (state.filterOpen) { state.filterOpen = false; renderFilter(); }
});

// ---------- layout ----------
function measure() {
  const w = root.clientWidth;
  const nextWide = w >= 600;
  root.classList.toggle('wide', nextWide);
  root.classList.toggle('tight', w < 390);
  const gh = el.grid.clientHeight;
  const nextRoomy = nextWide && gh / 6 >= 50 && el.grid.clientWidth / 7 >= 62;
  root.classList.toggle('roomy', nextRoomy);
  const changed = nextWide !== wide || nextRoomy !== roomy || (nextRoomy && Math.abs(gh - lastGridH) > 8);
  wide = nextWide;
  roomy = nextRoomy;
  lastGridH = gh;
  if (changed) renderGrid();
}
const ro = new ResizeObserver(() => measure());
ro.observe(root);
ro.observe(el.grid);

// ---------- live updates ----------
overlay.tasks.onChange((list) => {
  if (Array.isArray(list)) state.tasks = list;
  render();
});

setInterval(() => {
  const t = getToday();
  if (t !== today) {
    const wasToday = state.selected === today;
    today = t;
    if (wasToday) { state.selected = t; goToMonth(t); }
    render();
  }
  updatePill();
  checkNotify();
}, 20000);

renderDow();
measure();
render();
checkNotify();
